import{_ as e,o as t,c as s,a3 as p}from"./chunks/framework.DdpBa4_E.js";const o="/ReadBooks/assets/image-009.DMCZn2pZ.jpg",_="/ReadBooks/assets/image-011.ChPVjGrB.jpg",h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/43-是要700万日元还是要孩子？.md","filePath":"books/xialiu-shehui/43-是要700万日元还是要孩子？.md","lastUpdated":1794732511000}'),i={name:"books/xialiu-shehui/43-是要700万日元还是要孩子？.md"};function r(l,a,n,d,c,u){return t(),s("div",null,[...a[0]||(a[0]=[p('<h2 id="是要700万日元还是要孩子" tabindex="-1">是要700万日元还是要孩子？ <a class="header-anchor" href="#是要700万日元还是要孩子" aria-label="Permalink to &quot;是要700万日元还是要孩子？&quot;">​</a></h2><p>再来看表4-10：年收入在500万—700万日元的23名男性中，夫妇双方共同劳动的合计不超过13%，而妻子为专职家庭主妇或外出从事计时零工的占到了60.9%。与此相对，年收入超过700万日元的13名男性中，夫妇双方共同劳动的共有8人，占61.5%，而这些家庭全部是没有孩子的两人家庭（“丁克族”）；妻子为专职家庭主妇或外出做些零工的有孩子的家庭有4人，占到了30.8%。</p><p>表4-10　不同收入层次的团块次代男性的家庭形态</p><p><img src="'+o+'" alt="" loading="lazy"></p><p>资料出处：Culture Studies研究所、e-FALCON共同实施的“欲求调查”</p><p>从女性的角度来看（表4-11），家庭年收入超过700万日元的多数为“丁克族”，占全部被调查女性的28.6%，家庭年收入在500—700万日元的人群中“丁克族”有所减少，夫妇二人加一个孩子所组成的典型核心家庭上升至57.9%。</p><p>表4-11　不同收入层次的团块次代女性的家庭形态</p><p><img src="'+_+'" alt="" loading="lazy"></p><p>资料出处：Culture Studies研究所、e-FALCON共同实施的“欲求调查”</p><p>以上数字表明，由于家庭有了孩子之后，使得不少女性辞去工作，转而专事家务，相夫教子，因而有孩子的家庭其总收入一般会有所减少，大致保持在500万—700万日元的水平。假如家庭有了孩子仍然能够坚持夫妇共同工作的话，那么整个社会将会出现更多单就物质方面而言更加富裕的团块次代家庭。换句话说，我们完全有理由推测，有不少夫妇是为了保证家庭的总收入不低于700万日元，才不得不有所节制地少生孩子甚至不生孩子的。</p><p>团块次代中的许多人是在大都市郊外长大的，故此要想住得离父母近一些的话，势必就要远离城市中心，从而导致家庭中妻子一方无法继续工作下去。如果妻子还想继续工作下去的话，他们当然可以选择居住在城市中心，但此时必须确保家庭的总收入足以负担得起城市中心的高额住房支出；又或者，他们可以选择仍然居住在都市的郊外，但却必须依靠主要是来自妻子母亲的全面支援，帮助他们照看孩子。假如不能具备其中一个条件或同时具备两个条件，夫妇二人一面养育孩子，一面双方都继续工作，实在是一件非常困难的事情。</p><p>从女性方面来看，年收入低于150万日元的家庭中，夫妇二人以及由夫妇二人加一个孩子所组成的核心家庭占了60%还多。这其中除了个别笔误答错的之外，相当多的部分是那种婚前已怀孕生子、最后不得不结婚的年轻家庭。</p>',12)])])}const f=e(i,[["render",r]]);export{h as __pageData,f as default};
